import{_ as d,a0 as p,w as r,s as c,I as i,x as o,a1 as l,A as s,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"使用 GTWS 管理复杂的 Git 工作空间 | LCTT x X-CMD","titleTemplate":false,"description":"使用 GTWS 管理复杂的 Git 工作空间 | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 GTWS 管理复杂的 Git 工作空间 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 GTWS 管理复杂的 Git 工作空间 | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20200213 Manage complex Git workspaces with Great Teeming Workspaces","title":"使用 GTWS 管理复杂的 Git 工作空间","tag":"202004","desc":""},"relativePath":"202004/20200213 Manage complex Git workspaces with Great Teeming Workspaces.md","filePath":"[post].md"}'),n={name:"202004/20200213 Manage complex Git workspaces with Great Teeming Workspaces.md"};function g(u,e,m,T,h,b){const t=p("Link");return r(),c("div",null,[e[20]||(e[20]=i("h1",{id:"使用-gtws-管理复杂的-git-工作空间",tabindex:"-1"},[o("使用 GTWS 管理复杂的 Git 工作空间 "),i("a",{class:"header-anchor",href:"#使用-gtws-管理复杂的-git-工作空间","aria-label":"Permalink to “使用 GTWS 管理复杂的 Git 工作空间”"},"​")],-1)),e[21]||(e[21]=i("blockquote",null,[i("p",null,"GTWS 是一系列脚本，它使我们在开发环境中管理不同的项目和项目的各个版本变得很容易。")],-1)),e[22]||(e[22]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202004/27/182149xh9s7kb5bkf5875b.jpg",alt:""})],-1)),i("p",null,[l(t,{href:"https://github.com/dang/gtws"},{default:s(()=>[...e[0]||(e[0]=[o("Great Teeming Workspaces",-1)])]),_:1}),e[1]||(e[1]=o("（GTWS）是一个 Git 的复杂工作空间管理工具包，它使我们在开发环境中管理不同的项目和项目的各个版本变得很容易。",-1))]),i("p",null,[e[3]||(e[3]=o("有点像 Python 的 ",-1)),l(t,{href:"https://docs.python.org/3/library/venv.html"},{default:s(()=>[...e[2]||(e[2]=[o("venv",-1)])]),_:1}),e[4]||(e[4]=o("，但不是为 Python 语言准备的。GTWS 用来管理多个项目的多个版本的工作空间。你可以很容易地创建、更新、进入和离开工作空间，每个项目或版本的组合（最多）有一个本地的 origin，用来与 upstream 同步 — 其余的所有工作空间都从本地的 origin 更新。",-1))]),e[23]||(e[23]=a('<h3 id="部署" tabindex="-1">部署 <a class="header-anchor" href="#部署" aria-label="Permalink to “部署”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>${GTWS_ORIGIN}/&lt;project&gt;/&lt;repo&gt;[/&lt;version&gt;]</span></span>\n<span class="line"><span>${GTWS_BASE_SRCDIR}/&lt;project&gt;/&lt;version&gt;/&lt;workspacename&gt;/{&lt;repo&gt;[,&lt;repo&gt;...]}</span></span></code></pre></div><p>源代码目录的每一级（包括全局的家目录）可以包含一个 <code>.gtwsrc</code> 文件，这个文件中维护与当前级相关的设置和 bash 代码。每一级的配置会覆盖上一级。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>用下面的命令检出 GTWS：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone https://github.com/dang/gtws.git</span></span></code></pre></div><p>配置你的 <code>${HOME}/.gtwsrc</code>。它应该包含 <code>GTWS_ORIGIN</code>，也可以再包含 <code>GTWS_SETPROMPT</code>。</p><p>把仓库目录加到环境变量中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export PATH=&quot;${PATH}:/path/to/gtws</span></span></code></pre></div><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h3><p>通过级联 <code>.gtwsrc</code> 文件来进行配置。它从根目录向下遍历，会执行在每级目录中找到的 <code>.gtwsrc</code> 文件。下级目录的文件会覆盖上一级。</p><p>在你最上层的文件 <code>~/.gtws/.gtwsrc</code> 中进行如下设置：</p><ul><li><code>GTWS_BASE_SRCDIR</code>：所有项目源文件目录树的基目录。默认为 <code>$HOME/src</code>。</li><li><code>GTWS_ORIGIN</code>： 指定 origin git 目录树的路径。默认为 <code>$HOME/origin</code>。</li><li><code>GTWS_SETPROMPT</code>： 可选配置。如果配置了这个参数，shell 提示符会有工作空间的名字。</li><li><code>GTWS_DEFAULT_PROJECT</code>： 不指定项目或项目未知时默认的项目名。如果不指定，使用命令行时必须指明项目。</li><li><code>GTWS_DEFAULT_PROJECT_VERSION</code>： 检出的默认版本。默认为 <code>master</code>。</li></ul><p>在每个项目的根目录进行以下设置：</p><ul><li><code>GTWS_PROJECT</code>： 项目的名字（和基目录）。</li><li><code>gtws_project_clone</code>： 这个函数用于克隆一个项目的指定版本。如果未定义，它会假定项目的 origin 对每一个版本都有一个单独的目录，这样会导致克隆一堆 Git 仓库。</li><li><code>gtws_project_setup</code>： 在克隆完所有的仓库后，可以选择是否调用这个函数，调用后可以对项目进行必要的配置，如在 IDE 中配置工作空间。</li></ul><p>在项目版本级进行以下设置：</p><ul><li><code>GTWS_PROJECT_VERSION：</code> 项目的版本。用于正确地从 origin 拉取代码。类似 Git 中的分支名字。</li></ul><p>下面这些参数可以在目录树的任意地方进行配置，如果能生效，它们可以被重写多次：</p><ul><li><code>GTWS_PATH_EXTRA</code>： 这些是工作空间中加到路径后的额外的路径元素。</li><li><code>GTWS_FILES_EXTRA</code>： 这些是不在版本控制内，但应该在工作空间中被检出的额外的文件。这些文件包括 <code>.git/info/exclude</code>，每个文件都与仓库的基目录相关联。</li></ul><h3 id="origin-目录" tabindex="-1">origin 目录 <a class="header-anchor" href="#origin-目录" aria-label="Permalink to “origin 目录”">​</a></h3><p><code>GTWS_ORIGIN</code> （大部分脚本中）指向拉取和推送的原始 Git 检出目录。</p><p><code>${GTWS_ORIGIN}</code> 部署：</p><ul><li><code>/&lt;project&gt;</code><ul><li>这是一个项目的仓库的基目录。</li><li>如果指定了 <code>gtws_project_clone</code>，你可以配置任意的部署路径。</li><li>如果没有指定 <code>gtws_project_clone</code>，这个路径下必须有个名为 <code>git</code> 的子目录，且 <code>git</code> 目录下有一系列用来克隆的裸 Git 仓库。</li></ul></li></ul><h3 id="工作流示例" tabindex="-1">工作流示例 <a class="header-anchor" href="#工作流示例" aria-label="Permalink to “工作流示例”">​</a></h3><p>假设你有一个项目名为 <code>Foo</code>，它的 upstream 为 <code>github.com/foo/foo.git</code>。这个仓库有个名为 <code>bar</code> 的子模块，它的 upstream 是 <code>github.com/bar/bar.git</code>。Foo 项目在 master 分支开发，使用稳定版本的分支。</p><p>为了能在 Foo 中使用 GTWS，你首先要配置目录结构。本例中假设你使用默认的目录结构。</p><ul><li>配置你最上层的 <code>.gtwsrc</code>： <ul><li><code>cp ${GTWS_LOC}/examples/gtwsrc.top ~/.gtwsrc</code></li><li>根据需要修改 <code>~/.gtwsrc</code>。</li></ul></li><li>创建顶级目录： <ul><li><code>mkdir -p ~/origin ~/src</code></li></ul></li><li>创建并配置项目目录： <ul><li><p><code>mkdir -p ~/src/foo</code></p><p><code>cp ${GTWS_LOC}/examples/gtwsrc.project ~/src/foo/.gtwsrc</code></p></li><li><p>根据需要修改 <code>~/src/foo/.gtwsrc</code>。</p></li></ul></li><li>创建并配置 master 版本目录： <ul><li><p><code>mkdir -p ~/src/foo/master</code></p><p><code>cp ${GTWS_LOC}/examples/gtwsrc.version ~/src/foo/master/.gtwsrc</code></p></li><li><p>根据需要修改 <code>~/src/foo/master/.gtwsrc</code>。</p></li></ul></li><li>进入版本目录并创建一个临时工作空间来配置镜像： <ul><li><p><code>mkdir -p ~/src/foo/master/tmp</code></p><p><code>cd ~/src/foo/master/tmp</code></p><p><code>git clone --recurse-submodules git://github.com/foo/foo.git</code></p><p><code>cd foo</code></p><p><code>gtws-mirror -o ~/origin -p foo</code>（译注：这个地方原文有误，不加 <code>-s</code> 参数会报错）</p></li><li><p>上面命令会创建 <code>~/origin/foo/git/foo.git</code> 和 <code>~/origin/foo/submodule/bar.git</code>。</p></li><li><p>以后的克隆操作会从这些 origin 而不是 upstream 克隆。</p></li><li><p>现在可以删除工作空间了。</p></li></ul></li></ul><p>到现在为止，Foo 的 master 分支的工作可以结束了。假设你现在想修复一个 bug，名为 <code>bug1234</code>。你可以脱离你当前的工作空间为修复这个 bug 单独创建一个工作空间，之后在新创建的工作空间中开发。</p><ul><li>进入版本目录，创建一个新的工作空间： <ul><li><p><code>cd ~/src/foo/master</code></p><p><code>mkws bug1234</code></p></li><li><p>上面的命令创建了 <code>bug1234/</code>，在这个目录下检出了 Foo（和它的子模块 <code>bar</code>），并创建了 <code>build/foo</code> 来构建它。</p></li></ul></li><li>有两种方式进入工作空间： <ul><li><p><code>cd ~/src/foo/master/bug1234</code></p><p><code>startws</code></p><p>或者</p><p><code>cd ~/src/foo/master/</code></p><p><code>startws bug1234</code></p></li><li><p>上面的命令在 <code>bug1234</code> 工作空间中开启了一个子 shell。这个 shell 有 GTWS 的环境和你在各级 <code>.gtwsrc</code> 文件中设置的环境。它也把你工作空间的基目录加入到了 CD，因此你可以从 base 路径 <code>cd</code> 到相关的目录中。</p></li><li><p>现在你可以修复 <code>bug1234</code> 了，构建、测试、提交你的修改。当你可以把代码推送到 upstream 时，执行下面的命令：</p><p><code>cd foo</code></p><p><code>wspush</code></p></li><li><p><code>wspush</code> 会把代码推送到与你工作空间相关的分支 — 先推送到本地的 origin，再推送到 upstream。</p></li><li><p>当 upstream 有修改时，你可以用下面的命令同步到本地：</p><p><code>git sync</code></p></li><li><p>上面的命令调用了 GTWS 的 <code>git-sync</code> 脚本，会从本地 origin 更新代码。使用下面的命令来更新本地的 origin：</p><p><code>git sync -o</code></p></li><li><p>上面的命令会更新你本地的 origin 和子模块的镜像，然后用那些命令来更新你的检出仓库的代码。<code>git-sync</code> 也有一些其他的很好的工鞥。</p></li><li><p>当要结束工作空间中的工作时，直接退出 shell：</p><p><code>exit</code></p></li><li><p>你可以在任何时间重复进入工作空间，也可以在同一时间在相同的工作空间中开多个 shell。</p></li></ul></li><li>当你不需要某个工作空间时，你可以使用 <code>rmws</code> 来删除它，或者直接删除它的目录树。</li><li>还有一个脚本 <code>tmws</code> 使用 tmux 进入工作空间，能创建一系列的窗口/窗格，这完美契合我的工作流。你可以根据你自己的需求来修改它。</li></ul><hr>',30)),i("p",null,[e[6]||(e[6]=o("via: ",-1)),l(t,{href:"https://opensource.com/article/20/2/git-great-teeming-workspaces"},{default:s(()=>[...e[5]||(e[5]=[o("https://opensource.com/article/20/2/git-great-teeming-workspaces",-1)])]),_:1})]),i("p",null,[e[11]||(e[11]=o("作者：",-1)),l(t,{href:"https://opensource.com/users/dang"},{default:s(()=>[...e[7]||(e[7]=[o("Daniel Gryniewicz",-1)])]),_:1}),e[12]||(e[12]=o(" 选题：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:s(()=>[...e[8]||(e[8]=[o("lujun9972",-1)])]),_:1}),e[13]||(e[13]=o(" 译者：",-1)),l(t,{href:"https://github.com/lxbwolf"},{default:s(()=>[...e[9]||(e[9]=[o("lxbwolf",-1)])]),_:1}),e[14]||(e[14]=o(" 校对：",-1)),l(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[10]||(e[10]=[o("wxy",-1)])]),_:1})]),i("p",null,[e[17]||(e[17]=o("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[15]||(e[15]=[o("LCTT",-1)])]),_:1}),e[18]||(e[18]=o(" 原创编译，",-1)),l(t,{href:"https://linux.cn/"},{default:s(()=>[...e[16]||(e[16]=[o("Linux中国",-1)])]),_:1}),e[19]||(e[19]=o(" 荣誉推出",-1))])])}const w=d(n,[["render",g]]);export{k as __pageData,w as default};
